// Deux processus PHP réellement concurrents, synchronisés au même instant.
$db->insert('employe',['matricule'=>'RACE','nom'=>'Concurrence','prenoms'=>'Test','service_id'=>1,'badge_token'=>bin2hex(random_bytes(32)),'actif'=>1]);$raceEmp=(int)$db->fetchOne("SELECT id FROM employe WHERE matricule='RACE'");$db->insert('affectation_horaire',['employe_id'=>$raceEmp,'type_horaire_id'=>1,'date_debut'=>'2019-01-01','date_fin'=>null]);
function race(string $mode,int $id):array{
 putenv('CANTINE_RACE_START='.(microtime(true)+0.5));$base=[PHP_BINARY];if(str_contains(basename(PHP_BINARY),'frankenphp')){$base[]='php-cli';}$base[]=__DIR__.'/concurrence_worker.php';$base[]=$mode;$base[]=(string)$id;$jobs=[];
 for($i=0;$i<2;$i++){$pipes=[];$proc=proc_open($base,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($proc)){throw new RuntimeException('Processus PHP indisponible');}fclose($pipes[0]);$jobs[]=[$proc,$pipes];}
 $results=[];foreach($jobs as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($proc);$r=json_decode($out,true);if($code!==0||!is_array($r)){throw new RuntimeException('Processus concurrence échoué : '.$out.$err);}$results[]=$r;}return $results;
}
